import {icon} from "./icons.js";
import {VIEW_LABELS} from "../date.js";

export function renderShell() {
  return `<div class="app-shell"><div class="sidebar-overlay" data-action="close-sidebar"></div><aside id="sidebar" class="sidebar" aria-label="Menu de Tempo"></aside><main class="main"><header class="workspace-header"><div class="workspace-name"><button class="icon-button menu-button" data-action="toggle-sidebar" aria-label="Ouvrir le menu" aria-expanded="false" aria-controls="sidebar">${icon("menu")}<span id="tempo-menu-notifications-count" class="tempo-menu-notifications-count" aria-hidden="true" hidden></span></button><nav id="workspace-breadcrumb" class="workspace-breadcrumb" aria-label="Fil d’Ariane"></nav><span class="workspace-separator"></span><span class="personal-label"><span></span>Personnel</span></div><div class="workspace-actions"><button class="secondary-button event-types-button" data-action="manage-event-types" aria-label="Gérer les types d’événement">${icon("edit")}<span>Types</span></button><button class="primary-button create-event-button" data-action="create-event" title="Créer un événement ou une tâche (N)">${icon("plus")}<span>Créer</span></button><button class="jump-button" data-action="jump" aria-label="Aller à une date">${icon("calendar")}<span>Aller à une date</span><kbd>G</kbd></button></div></header><section class="calendar-workspace"><div id="events-status" class="events-status" role="status" aria-live="polite" hidden></div><div id="moodle-sync-status" class="events-status" role="status" hidden></div><div class="calendar-toolbar"><div class="period-controls"><h1 id="period-title"></h1><div class="period-navigation"><button class="icon-button" data-action="prev" aria-label="Mois précédent">${icon("chevronLeft")}</button><button class="icon-button" data-action="next" aria-label="Mois suivant">${icon("chevronRight")}</button></div><button class="today-button" data-action="today" title="Aller à aujourd’hui (T)">Aujourd’hui</button></div><div class="view-switch" role="group" aria-label="Vue du calendrier">${["month", "week", "day"].map(view => `<button data-action="${view}" aria-pressed="false" title="Vue ${VIEW_LABELS[view].toLowerCase()} (${view[0].toUpperCase()})">${VIEW_LABELS[view]}</button>`).join("")}</div></div><div id="calendar-content" class="calendar-content" tabindex="-1"></div><footer class="calendar-footer"><span id="view-hint"></span><span class="timezone-info">${icon("globe")}<span>Toronto</span><span class="footer-dot">·</span><span id="timezone-offset"></span></span></footer></section></main></div>`;
}
export function renderBreadcrumb(state) {
  const separator = `<span class="breadcrumb-separator">${icon("chevronRight")}</span>`;
  if (state.page === "documents") return `<button class="breadcrumb-parent" data-action="month">Calendrier</button>${separator}<span class="breadcrumb-current" aria-current="page">Documents</span>`;
  const crumbs = [{label: "Calendrier", action: "month"}];
  if (state.view === "week" || state.view === "day") crumbs.push({label: VIEW_LABELS.week, action: "week"});
  if (state.view === "day") crumbs.push({label: VIEW_LABELS.day, action: "day"});
  return crumbs.map((crumb, index) => index === crumbs.length - 1 ? `<span class="breadcrumb-current" aria-current="page">${crumb.label}</span>` : `<button class="breadcrumb-parent" data-action="${crumb.action}">${crumb.label}</button>`).join(separator);
}
